// HasQuotaDays applies the HasEdge predicate on the "quota_days" edge.
func HasQuotaDays() predicate.MailAccount {
	return predicate.MailAccount(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, QuotaDaysTable, QuotaDaysColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasQuotaDaysWith applies the HasEdge predicate on the "quota_days" edge with a given conditions (other predicates).
func HasQuotaDaysWith(preds ...predicate.MailQuota) predicate.MailAccount {
	return predicate.MailAccount(func(s *sql.Selector) {
		step := newQuotaDaysStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

